from decimal import Decimal
from typing import Any


_ZERO = Decimal("0")
_EIGHT = Decimal("8")
_TEN = Decimal("10")


def _decimal_nvl(value: Any) -> Decimal:
    """Apply legacy numeric NVL/coercion without binary floating-point math."""
    if value is None:
        return _ZERO
    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return _ZERO
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def sweep(
    accounts: list[dict], orders: list[dict]
) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    exposure_by_account: dict[Any, Decimal] = {}
    for order in orders:
        if order.get("DEL_FLG") == "Y":
            continue
        if order.get("STAT_CD") != "I":
            continue

        acct_id = order.get("ACCT_ID")
        exposure_by_account[acct_id] = (
            exposure_by_account.get(acct_id, _ZERO)
            + _decimal_nvl(order.get("TOT_AMT"))
        )

    eligible_indices = [
        index
        for index, account in enumerate(new_accounts)
        if account.get("DEL_FLG") != "Y"
        and account.get("ACCT_TYP") == "C"
    ]
    eligible_indices.sort(key=lambda index: new_accounts[index].get("ACCT_ID"))

    for index in eligible_indices:
        account = new_accounts[index]
        acct_id = account.get("ACCT_ID")
        exposure = exposure_by_account.get(acct_id, _ZERO)
        credit_limit = _decimal_nvl(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if (
            exposure <= credit_limit * _EIGHT / _TEN
            and account.get("CRED_HOLD") == "Y"
        ):
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
